//! Static game data (tile/wall colors and names, item names), generated by tools/gen_data.py.
use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(Deserialize)]
struct TileFile {
    tiles: Vec<(String, u32, u8)>,
    frames: HashMap<String, Vec<(i32, i32, String)>>,
    walls: Vec<u32>,
    #[serde(rename = "wallNames")]
    wall_names: Vec<String>,
}

pub struct Data {
    pub tile_name: Vec<String>,
    pub tile_color: Vec<u32>,
    pub frames: HashMap<u16, Vec<(i32, i32, String)>>,
    pub wall_color: Vec<u32>,
    pub wall_name: Vec<String>,
    pub items: Vec<String>,
    pub item_by_name: HashMap<String, i32>,
}

static DATA: OnceLock<Data> = OnceLock::new();

pub fn data() -> &'static Data {
    DATA.get_or_init(|| {
        let t: TileFile = serde_json::from_str(include_str!("../data/tiles.json")).expect("tiles.json");
        let items: Vec<String> = serde_json::from_str(include_str!("../data/items.json")).expect("items.json");
        let mut item_by_name = HashMap::new();
        for (i, n) in items.iter().enumerate() {
            if !n.is_empty() {
                item_by_name.entry(n.to_lowercase()).or_insert(i as i32);
            }
        }
        Data {
            tile_name: t.tiles.iter().map(|x| x.0.clone()).collect(),
            tile_color: t.tiles.iter().map(|x| x.1).collect(),
            frames: t.frames.into_iter().map(|(k, v)| (k.parse().unwrap_or(0), v)).collect(),
            wall_color: t.walls,
            wall_name: t.wall_names,
            items,
            item_by_name,
        }
    })
}

impl Data {
    pub fn item_name(&self, id: i32) -> String {
        if id >= 0 && (id as usize) < self.items.len() && !self.items[id as usize].is_empty() {
            self.items[id as usize].clone()
        } else {
            format!("Item #{id}")
        }
    }
    /// Name of a framed object given its tile type and top-left frame.
    pub fn frame_name(&self, tile: u16, u: i32, v: i32) -> Option<String> {
        let fr = self.frames.get(&tile)?;
        let mut best: Option<&(i32, i32, String)> = None;
        for f in fr {
            if f.0 <= u && f.1 <= v {
                match best {
                    Some(b) if b.0 > f.0 || (b.0 == f.0 && b.1 > f.1) => {}
                    _ => best = Some(f),
                }
            }
        }
        best.map(|b| b.2.clone())
    }
    pub fn tile_name(&self, t: u16) -> &str {
        self.tile_name.get(t as usize).map(|s| s.as_str()).unwrap_or("Unknown tile")
    }
}
